if (root == nullptr) {
    root = new TreeNode(item);
    return;
}

if (item < root->data) {
    bstInsert(root->left, item);
} else if (item > root->data) {
    bstInsert(root->right, item);
}
// If item == root->data, typically BSTs do not insert duplicates.

